select 'feed|' || f.id || '|' || p.name || '|' || f.consecutive_failures || '|' || coalesce(to_char(f.last_success_at, 'HH24:MI'), 'never') || '|' || coalesce(f.last_error, '-') || '|' || (SELECT count(*) FROM articles a WHERE a.publisher_id = f.publisher_id AND a.fetched_at > now() - interval '1 hour') || ' new' || '|' || (SELECT count(*) FROM articles a WHERE a.publisher_id = f.publisher_id AND a.fetched_at > now() - interval '1 hour' AND a.published_at IS NULL) || ' undated' FROM feeds f JOIN publishers p ON p.id = f.publisher_id WHERE f.id IN (573, 1523) ORDER BY f.id;
select 'sample|' || to_char(published_at, 'HH24:MI') || '|' || category || '|' || left(headline, 90) FROM articles WHERE publisher_id = 573 ORDER BY id DESC LIMIT 4;
select 'ok|' || count(*) FILTER (WHERE last_success_at > now() - interval '30 minutes') || ' of 2' FROM feeds WHERE id IN (573, 1523);
